const MIN_REASONABLE_YEAR = 1990;
/** Reject far-future OCR garbage (QA saw 2050 / 46256). Allow a small forward buffer. */
const MAX_REASONABLE_YEAR = new Date().getUTCFullYear() + 1;

/**
 * Format dates for operational ledgers. Rejects OCR/Excel garbage years
 * (e.g. 46256, 2050 far-future invoice noise) so the UI stays auditable.
 */
export function sanitizeDisplayDate(
  value: string | number | Date | null | undefined,
  fallback = 'Date unavailable'
): string {
  if (value == null || value === '') return fallback;

  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) return fallback;

  const year = parsed.getUTCFullYear();
  if (year < MIN_REASONABLE_YEAR || year > MAX_REASONABLE_YEAR) {
    return fallback;
  }

  return new Intl.DateTimeFormat('en-IN', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    timeZone: 'UTC',
  }).format(parsed);
}

export function isReasonableTransactionDate(value: string | number | Date | null | undefined): boolean {
  if (value == null || value === '') return false;
  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) return false;
  const year = parsed.getUTCFullYear();
  return year >= MIN_REASONABLE_YEAR && year <= MAX_REASONABLE_YEAR;
}
